UML Generator.class_diagram:
classDiagram
    class User {
        +userId
        +name
        +email
        +password
    }
    class Restaurant {
        +restaurantId
        +name
        +address
    }
    class Menu {
        +menuId
        +title
    }
    class FoodItem {
        +itemId
        +name
        +price
    }
    class Order {
        +orderId
        +status
        +totalAmount
    }
    class DeliveryPartner {
        +partnerId
        +name
    }
    User "1" --> "*" Order : places
    Order "*" --> "1" DeliveryPartner : assigned to
    Restaurant "1" --> "*" Menu : has
    Menu "1" --> "*" FoodItem : contains
    Order "*" --> "*" FoodItem : includes
    Restaurant "1" --> "*" Order : receives

